output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in single-file aisles that run between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "betweenOpposingShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_pedestrian_aisle_with_cart",
    "text": "An agent may not push a cart into a pedestrian-only single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "pedestrianShelfAisle": {
          "and": [
            "singleFileAisle",
            "betweenOpposingShelves"
          ]
        }
      },
      "events": {
        "enterPedestrianShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "pedestrianShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterPedestrianShelfAisleWithCart"
    }
  },
  {
    "id": "park_cart_at_shelf_aisle_mouth",
    "text": "Upon arriving with a cart at the mouth of the narrow shelf aisle, the agent is obliged to park the cart there before shopping in that aisle.",
    "abstraction": {
      "state_properties": {
        "upperShelfAisleMouth": "at(3,3)",
        "cartAtUpperShelfAisleMouth": {
          "and": [
            "upperShelfAisleMouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "arriveAtUpperShelfAisleMouthWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "upperShelfAisleMouth"
        },
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "cartAtUpperShelfAisleMouth",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtUpperShelfAisleMouthWithCart",
      "discharge": "parkCartAtMouth"
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_aisle",
    "text": "After entering a pedestrian-only shelf aisle without a cart, the agent is obliged to retrieve the parked cart before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "pedestrianShelfAisle": {
          "and": [
            "singleFileAisle",
            "betweenOpposingShelves"
          ]
        }
      },
      "events": {
        "enterPedestrianShelfAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "pedestrianShelfAisle"
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterPedestrianShelfAisleOnFoot",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "no_cart_pick_in_narrow_shelf_aisle",
    "text": "Items in single-file shelf aisles must be picked without holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "narrowShoppingAisle": {
          "and": [
            "singleFileAisle",
            "betweenOpposingShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "narrowShoppingAisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_only_in_spacious_open_aisle",
    "text": "A cart may be parked only in a spacious open aisle, not inside or immediately beside shelf aisles.",
    "abstraction": {
      "state_properties": {
        "spaciousAisle": {
          "gt": [
            "freeWidthH",
            2
          ]
        },
        "openAisle": {
          "not": "adjShelf"
        },
        "cartParkingZone": {
          "and": [
            "spaciousAisle",
            "openAisle"
          ]
        }
      },
      "events": {
        "dropCartOutsideParkingZone": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "cartParkingZone"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "dropCartOutsideParkingZone"
    }
  },
  {
    "id": "no_cart_between_opposing_shelves",
    "text": "Carts are prohibited anywhere between shelves on both sides of the aisle.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenOpposingShelves"
        ]
      }
    }
  },
  {
    "id": "no_cart_into_low_passing_width",
    "text": "An agent may not move a cart into a cell whose horizontal passing width is too small for carts to pass safely.",
    "abstraction": {
      "state_properties": {
        "lowHorizontalPassingWidth": {
          "le": [
            "freeWidthH",
            2
          ]
        }
      },
      "events": {
        "pushCartIntoLowPassingWidth": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "lowHorizontalPassingWidth"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoLowPassingWidth"
    }
  }
]
